from det2 import *
rng=np.random.default_rng(1)
for site in ['model.layers.14.linear_attn.out_proj','model.layers.18.linear_attn.out_proj']:
  W,P=data(site)
  res={K:[] for K in [64,128,256]}
  for rep in range(2):
      perm=rng.permutation(64); tr=perm[:48]; te=perm[48:]
      Vall=basis(W,P,tr)
      for K in res:
        a=build(W,P,tr,K,Vall)
        res[K].append([ (W[te,-1]@a).mean(), (W[te,-1]@a).std(), (P[te,-1]@a).mean(), (P[te,-1]@a).std(), np.abs(P[te,:-1]@a).max(), (P[te,:-1]@a).std(), (W[te,:-3]@a).std()])
